/**
 * @file std/algorithm/algorithm.az
 *
 * Additional algorithm utilities: merge sort, sortBy, groupBy, etc.
 *
 * @since 0.1
 */
@Supress(.Unused)
module std.algorithm

import std.container.array::*
import std.traits::Order

/**
 * Merge sort - O(n log n) stable sorting algorithm.
 */
@Experimental(since: "0.1")
func<T: Order> mergeSort(arr: Array<T>): Array<T> {
    if arr.size <= 1 then return arr
    var mid: Int = arr.size / 2
    var {left, right}: Array<T> = {.() * mid, .() * arr.size - mid}
    for i: Int in 0..mid then left[i] = arr[i]
    for j: Int in 0..arr.size then right[j] = arr[mid + j]
    var {sortedLeft, sortedRight}: Array<T> = mergeSort{(left), (right)}
    return merge(sortedLeft, sortedRight)
}

/**
 * Merges two sorted arrays into one sorted array.
 */
@Experimental(since: "0.1")
func<T: Order> merge(a: Array<T>, b: Array<T>): Array<T> {
    var result: Array<T> = .() * a.size + b.size
    var {ri, ai, bi}: Int = 0
    while ai < a.size && bi < b.size then result[ri++] = if a[ai] <= b[bi] then a[ai++] else b[bi++]
    while ai < a.size then result[ri++] = a[ai++]
    while bi < b.size then result[ri++] = b[bi++]
    return result
}

/**
 * Sorts by a key extracted from each element.
 *
 * The key is its own type: sorting people by age means a `(Person) -> Int`,
 * and a key function forced to return the element type could not express
 * that at all. `K` need only be [Order] - the element type need not be
 * ordered, which is the point of sorting by a key.
 *
 * Stable, and O(n log n) - the same bottom-up merge [sort] uses, carrying
 * the computed keys alongside the elements so a key is never recomputed
 * mid-sort.
 *
 * @param arr The array to sort.
 * @param key Extracts the value to order by.
 * @return A new array ordered by [key]; the original is unchanged.
 */
@Experimental(since: "0.1")
func<T, K> sortBy(arr: Array<T>, key: (T) -> K): Array<T> where K: Order
out {
    assert it.size == arr.size panic "sortBy must preserve length"
} scope {
    fin count = arr.size
    var result: Array<T> = .() * count
    for i: Int in 0..<count then result[i] = arr[i]
    if count <= 1 then return result

    // Keys are computed once per element rather than once per comparison:
    // a key function may be arbitrarily expensive, and a comparison sort
    // asks O(n log n) times.
    var keys: Array<K> = .() * count
    for i: Int in 0..<count then keys[i] = key(result[i])

    var width: Int = 1
    var scratch: Array<T> = .() * count
    var scratchKeys: Array<K> = .() * count
    while width < count {
        for lo: Int in 0..count {
            var mid = lo + width
            if mid > count then mid = count
            var hi = lo + width + width
            if hi > count then hi = count
            var {left, right, at}: Int = {lo, mid, lo}
            while at < hi {
                fin takeLeft: Bool = when {
                    left >= mid -> false
                    right >= hi -> true
                    else -> keys[left] <= keys[right]
                }
                if takeLeft {
                    scratch[at] = result[left]
                    scratchKeys[at] = keys[left++]
                } else {
                    scratch[at] = result[right]
                    scratchKeys[at] = keys[right++]
                }
                at++
            }
            lo += width * 2
        }
        for i: Int in 0..<count {
            result[i] = scratch[i]
            keys[i] = scratchKeys[i]
        }
        width *= 2
    }
    return result
}

/**
 * Groups elements by a key function.
 * Returns array of arrays where each sub-array has elements with the same key.
 */
@Experimental(since: "0.1")
func<T> groupBy(arr: Array<T>, key: (T) -> T): Array<T> {
    var keys: Array<T> = .() * arr.size
    var groups: Array<T> = .() * arr.size
    var keyCount: Int = 0
    for i: Int in 0..<arr.size {
        var k: T = key(arr[i])
        var found = -1
        for j: Int in 0..<keyCount then if keys[j] == k then found = j
        if found == -1 {
            keys[keyCount] = k
            groups[keyCount++] = [arr[i]]
        } else {
            var g: Array<T> = groups[found]
            g[g.size] = arr[i]
            groups[found] = g
        }
    }
    // Trim groups to actual count
    var trimmed: Array<T> = .() * keyCount
    for ti: Int in 0..<keyCount then trimmed[ti] = groups[ti]
    return trimmed
}

/**
 * Interleaves two arrays: [a1, b1, a2, b2, ...].
 */
@Experimental(since: "0.1")
func<T> interleave(a: Array<T>, b: Array<T>): Array<T> {
    var result: Array<T> = .() * a.size + b.size
    var {ri, maxLen}: Int = {0, a.size}
    if b.size > maxLen then maxLen = b.size
    for i: Int in 0..<maxLen then if i < {a, b}.size then result[ri++] = {a, b}[i]
    return result
}

/**
 * Returns a sliding window of given size over the array.
 */
@Experimental(since: "0.1")
func<T> windows(arr: Array<T>, size: Int): Array<T> {
    fin count: Int = if arr.size >= size then arr.size - size + 1 else 0
    var result: Array<T> = .() * count
    var {ri, i}: Int = 0
    while i + size <= arr.size {
        var w: Array<T> = .() * size
        for j: Int in 0..<size then w[j] = arr[i + j]
        result[ri++] = w
        i++
    }
    return result
}

/**
 * Returns array with elements at even indices.
 */
@Experimental(since: "0.1")
func<T> evens(arr: Array<T>): Array<T> {
    fin count: Int = (arr.size + 1) / 2
    var result: Array<T> = .() * count
    for i: Int in 0..<arr.size by 2 with index then result[index] = arr[i]
    return result
}

/**
 * Returns array with elements at odd indices.
 */
@Experimental(since: "0.1")
func<T> odds(arr: Array<T>): Array<T> {
    fin count: Int = arr.size / 2
    var result: Array<T> = .() * count
    for i: Int in 1..<arr.size by 2 with index then result[index] = arr[i]
    return result
}

