/**
 * @file std/container/list.az
 *
 * Proposed native list hierarchy for Azora, mirroring `map.az`.
 *
 * Lists come in two flavors:
 *
 * - `List<T>` is the read-only view: indexed access, search, and functional
 *   combinators that return fresh `List<T>` snapshots.
 * - `MutableList<T>` adds in-place mutation. Every mutation receives
 *   `self!`, so a caller holding only a shared `ref List<T>` view
 *   cannot mutate it.
 *
 * `ArrayList<T>` is the single concrete dynamic-array pack implementing both
 * specs. The `listOf`, `mutableListOf`, and `arrayListOf`
 * factories construct it; `listOf` and expose the read-only
 * `List<T>` view, `mutableListOf` exposes `MutableList<T>`.
 *
 * @since 0.1
 */
@Supress(.Unused)
module std.container.list

/**
 * Read-only behavior shared by every list implementation.
 *
 * `List` guarantees element ordering: iteration and indexed access follow
 * insertion order. A concrete pack may add stronger guarantees.
 *
 * @generic T The element type.
 */
@Experimental(since: "0.1")
spec List<T> {
    /** Number of elements. */
    prop &.size: Int

    /** Whether this list has no elements. */
    prop &.isEmpty: Bool

    /** Whether this list has at least one element. */
    prop &.isNotEmpty: Bool

    /** The first element. Asserts when empty. */
    prop &.first: T

    /** The last element. Asserts when empty. */
    prop &.last: T

    /** A new list with the elements of this one in reverse order. */
    prop &.reversed: List<T>

    /** Returns the element at `index`. Asserts on an out-of-bounds index. */
    func &.get(index: Int): T

    /** Returns whether `element` is present. */
    func &.contains(element: T): Bool

    /** Returns the first index of `element`, or `-1` when absent. */
    func &.indexOf(element: T): Int

    /** Returns the last index of `element`, or `-1` when absent. */
    func &.lastIndexOf(element: T): Int

    /** Invokes `action` once for every element in order. */
    func &.forEach(action: (T) -> Unit)

    /** Returns a new list with each element transformed by `transform`. */
    func &.map(transform: (T) -> T): List<T>

    /** Returns a new list with only elements satisfying `predicate`. */
    func &.filter(predicate: (T) -> Bool): List<T>

    /** Returns whether at least one element satisfies `predicate`. */
    func &.any(predicate: (T) -> Bool): Bool

    /** Returns whether every element satisfies `predicate`. */
    func &.all(predicate: (T) -> Bool): Bool

    /** Returns whether no element satisfies `predicate`. */
    func &.none(predicate: (T) -> Bool): Bool

    /** Counts the elements satisfying `predicate`. */
    func &.count(predicate: (T) -> Bool): Int

    /** Returns a half-open `[from, to)` snapshot of this list. */
    func &.subList(from: Int, to: Int): List<T>

    /** `[a, b, c]` where a `List<T>` is expected: an `ArrayList<T>` in source order. */
    literal [...elements: T]: Self {
        return _arrayListOf(elements)
    }
}

/**
 * A List is cloned by duplicating its elements; it is never `Copy`,
 * because duplicating a collection implicitly would hide an allocation.
 */
@Since("0.1")
derive Clone for List

/**
 * Mutation behavior implemented by mutable list packs.
 *
 * Mutation always receives `self!`. Implementing this spec does not
 * weaken a `ref List<T>` view: callers holding only a shared reference can
 * still use only read operations.
 *
 * @generic T The element type.
 */
@Experimental(since: "0.1")
spec MutableList<T> : List<T> {
    /** Appends `element` to the end. */
    func &.add(element: T)

    /** Inserts `element` at `index`, shifting the suffix right. */
    func &.insert(index: Int, element: T)

    /** Replaces the element at `index`. */
    func &.set(index: Int, element: T)

    /** Removes and returns the element at `index`. */
    func &.removeAt(index: Int): T

    /** Removes and returns the first element. */
    func &.removeFirst(): T

    /** Removes and returns the last element. */
    func &.removeLast(): T

    /** Removes every element while retaining reusable internal capacity. */
    func &.clear()

    /** `[a, b, c]` where a `MutableList<T>` is expected: an `ArrayList<T>` in source order. */
    literal [...elements: T]: Self {
        return _arrayListOf(elements)
    }
}

/**
 * Dynamic-array pack backing both `List<T>` and `MutableList<T>`.
 *
 * Storage is a contiguous `T*` buffer that doubles on demand. Internal
 * fields are not exposed outside the pack.
 *
 * @generic T The element type.
 */
@Experimental(since: "0.1")
pack ArrayList<T> {
    var _data: T* = null
    var _size: Int = 0
    var _capacity: Int = 0
} // default constructor is .()

// count inserts an in contract, it must be >= 1

impl ArrayList<T> {
    // this is .() * 7
    ctor .() * count {
        self._data = alloc .() * count
        self._size = count
        self._capacity = count
    }

    // this is .(1, 2, 3)
    ctor .(...args: T) {
        self._data = alloc args
        self._size = args.length
        self._capacity = args.length
    }

    // this is .(5) * 10
    ctor .(fill: T) * count {
        self._data = alloc .(fill) * count
        self._size = count
        self._capacity = count
    }

    /** `[a, b, c]` where an `ArrayList<T>` is expected, in source order. */
    literal [...elements: T]: ArrayList<T> {
        return _arrayListOf(elements)
    }
}

/**
 * An ArrayList owns its backing buffer, so it moves and clones but never
 * copies implicitly - duplicating one allocates, and that cost stays in
 * sight at the call site as `.clone()`.
 */

@Since("0.1")
impl Clone for ArrayList {
    func &.clone() {
        var copy: ArrayList<T> = .()
        for i in 0..<self._size {
            copy.add(self._data[i])
        }
        return copy
    }
}

// ---------------------------------------------------------------------
// ArrayList implementation
// ---------------------------------------------------------------------

impl ArrayList<T> {
    /** Allocates the first buffer or doubles capacity, preserving existing elements. */
    @Experimental(since: "0.1")
    func !.grow() {
        assert self._capacity >= 0 panic "List capacity must be non-negative"
        assert self._capacity <= 1073741823 panic "List capacity overflow"
        fin newCap = if self._capacity == 0 then 8 else self._capacity * 2
        let newData: T* = alloc .() * newCap
        for i in 0..<self._size {
            newData[i] = self._data[i]
        }
        fin oldData = self._data
        self._data = newData
        self._capacity = newCap
        purge oldData
    }
}

impl List<T> for ArrayList<T> {
    prop &.size: Int = self._size
    prop &.isEmpty: Bool = self._size == 0
    prop &.isNotEmpty: Bool = self._size > 0

    prop &.first: T
    in {
        assert self._size > 0 panic "List is empty"
    } scope {
        return self._data[0]
    }

    prop &.last: T
    in {
        assert self._size > 0 panic "List is empty"
    } scope {
        return self._data[self._size - 1]
    }

    prop &.reversed: List<T> {
        var result: ArrayList<T> = .()
        var i = self._size - 1
        while i >= 0 {
            result.add(self._data[i])
            i--
        }
        return result
    }

    func &.get(index: Int): T
    in {
        assert index >= 0 panic "List index must be non-negative"
        assert index < self._size panic "List index out of bounds"
    } scope {
        return self._data[index]
    }

    func &.contains(element: T): Bool {
        for i in 0..<self._size {
            if self._data[i] == element {
                return true
            }
        }
        return false
    }

    func &.indexOf(element: T): Int {
        for i in 0..<self._size {
            if self._data[i] == element {
                return i
            }
        }
        return -1
    }

    func &.lastIndexOf(element: T): Int {
        var result = -1
        for i in 0..<self._size {
            if self._data[i] == element {
                result = i
            }
        }
        return result
    }

    func &.forEach(action: (T) -> Unit) {
        for i in 0..<self._size {
            action(self._data[i])
        }
    }

    func &.map(transform: (T) -> T): List<T> {
        var result: ArrayList<T> = .()
        for i in 0..<self._size {
            result.add(transform(self._data[i]))
        }
        return result
    }

    func &.filter(predicate: (T) -> Bool): List<T> {
        var result: ArrayList<T> = .()
        for i in 0..<self._size {
            if predicate(self._data[i]) {
                result.add(self._data[i])
            }
        }
        return result
    }

    func &.any(predicate: (T) -> Bool): Bool {
        return for i in 0..<self._size {
            if predicate(self._data[i]) {
                true
            }
        } else { false }
    }

    func &.all(predicate: (T) -> Bool): Bool {
        return for i in 0..<self._size {
            if !predicate(self._data[i]) {
                false
            }
        } else { true }
    }

    func &.none(predicate: (T) -> Bool): Bool {
        return for i in 0..<self._size {
            if predicate(self._data[i]) {
                false
            }
        } else { true }
    }

    func &.count(predicate: (T) -> Bool): Int {
        var c = 0
        for i in 0..<self._size {
            if predicate(self._data[i]) {
                c++
            }
        }
        return c
    }

    func &.subList(from: Int, to: Int): List<T> in {
        assert from >= 0 panic "subList from must be non-negative"
        assert to <= self._size panic "subList to out of bounds"
        assert from <= to panic "subList from must be <= to"
    } scope {
        var result: ArrayList<T> = .()
        for i in from..<to {
            result.add(self._data[i])
        }
        return result
    }
}

impl MutableList<T> for ArrayList<T> {
    func !.add(element: T) {
        if self._size >= self._capacity {
            self.grow()
        }
        self._data[self._size] = element
        self._size++
    }

    func !.insert(index: Int, element: T)
    in {
        assert index >= 0 panic "Insert index must be non-negative"
        assert index <= self._size panic "Insert index out of bounds"
    } scope {
        if self._size >= self._capacity {
            self.grow()
        }
        var i = self._size
        while i > index {
            self._data[i] = self._data[i - 1]
            i--
        }
        self._data[index] = element
        self._size++
    }

    func !.set(index: Int, element: T)
    in {
        assert index >= 0 panic "Set index must be non-negative"
        assert index < self._size panic "Set index out of bounds"
    } scope {
        self._data[index] = element
    }

    func !.removeAt(index: Int): T
    in {
        assert index >= 0 panic "Remove index must be non-negative"
        assert index < self._size panic "Remove index out of bounds"
    } scope {
        fin removed = self._data[index]
        for i in index..<self._size - 1 {
            self._data[i] = self._data[i + 1]
        }
        self._size--
        return removed
    }

    func !.removeFirst(): T
    in {
        assert self._size > 0 panic "List is empty"
    } scope {
        return self.removeAt(0)
    }

    func !.removeLast(): T
    in {
        assert self._size > 0 panic "List is empty"
    } scope {
        fin removed = self._data[self._size - 1]
        self._size--
        return removed
    }

    func !.clear() {
        fin oldData = self._data
        self._data = alloc .() * 8
        self._size = 0
        self._capacity = 8
        purge oldData
    }
}

// ---------------------------------------------------------------------
// Factories
// ---------------------------------------------------------------------

/** What every list literal builds: the elements, in order, sized for them. */
func<T> _arrayListOf(elements: Array<T>): ArrayList<T> {
    var result: ArrayList<T> = .()
    for i in 0..<elements.size {
        result.add(elements[i])
    }
    return result
}

@Experimental(since: "0.1")
func<T> listOf(...elements: T): List<T> {
    var result: ArrayList<T> = .()
    for i in 0..<elements.size {
        result.add(elements[i])
    }
    return result
}

@Experimental(since: "0.1")
func<T> mutableListOf(...elements: T): MutableList<T> {
    var result: ArrayList<T> = .()
    for i in 0..<elements.size {
        result.add(elements[i])
    }
    return result
}

@Experimental(since: "0.1")
func<T> arrayListOf(...elements: T): ArrayList<T> {
    var result: ArrayList<T> = .()
    for i in 0..<elements.size {
        result.add(elements[i])
    }
    return result
}

// ---------------------------------------------------------------------
// Operators
// ---------------------------------------------------------------------

@Experimental(since: "0.1")
oper[] ArrayList<T>&.(index: Int): T {
    assert index >= 0 && index < self._size panic "List index out of bounds"
    return self._data[index]
}

@Experimental(since: "0.1")
oper[]= ArrayList<T>!.(index: Int, element: T) {
    assert index >= 0 && index < self._size panic "List index out of bounds"
    self._data[index] = element
}

@Experimental(since: "0.1")
impl Into<String> for ArrayList<T> {
    prop &.into: String {
        var s = "["
        for i in 0..<self._size {
            s += if i > 0 { ", " } else { self._data[i] as String }
        }
        return s + "]"
    }
}

@Experimental(since: "0.1")
oper== ArrayList<T>&.(rhs: List<T>): Bool {
    if self._size != rhs.size {
        return false
    }
    return for i in 0..<self._size {
        if !(self.get(i) == rhs.get(i)) {
            false
        }
    } else { true }
}

@Experimental(since: "0.1")
oper!= ArrayList<T>&.(rhs: List<T>): Bool {
    return !(self == rhs)
}

// A list has no `hash` until an element's `Hash` can be required and called
// through a generic slot; `.hash` on an unconstrained `T` has no implementation.

test "list starts empty" {
    fin value: ArrayList<Int> = .()
    assert value.size == 0 && value.isEmpty panic "emptyList must contain no elements"
}

test "listOf preserves order" {
    fin value = listOf(3, 1, 2)
    assert value.size == 3 panic "listOf size changed"
    assert value.get(0) == 3 && value.get(1) == 1 && value.get(2) == 2 panic "listOf must preserve argument order"
}

test "mutableListOf accepts initial elements" {
    fin value = mutableListOf(1, 2, 3)
    assert value.size == 3 && value.get(0) == 1 && value.get(2) == 3 panic "mutableListOf order changed"
}

test "array list grows beyond initial capacity" {
    var value: ArrayList<Int> = .()
    for i in 0..<20 {
        value.add(i)
    }
    assert value.size == 20 && value[19] == 19 panic "list growth must preserve every element"
}

test "mutable list insert shifts the suffix" {
    var value = mutableListOf(1, 3)
    value.insert(1, 2)
    assert value.size == 3 && value.get(1) == 2 && value.get(2) == 3 panic "insert must shift the suffix"
}

test "mutable list set replaces in place" {
    var value = mutableListOf(1, 2, 3)
    value.set(0, 4)
    value.set(2, 6)
    assert value.size == 3 && value.get(0) == 4 && value.get(2) == 6 panic "replacement must not change size"
}

test "mutable list removals retain order" {
    var value = mutableListOf(1, 2, 3, 4)
    assert value.removeAt(1) == 2 panic "removeAt must return the removed value"
    assert value.removeFirst() == 1 panic "removeFirst must return the first value"
    assert value.removeLast() == 4 panic "removeLast must return the last value"
    assert value.size == 1 && value.get(0) == 3 panic "removals must preserve the remaining order"
}

test "list search reports first and last positions" {
    fin value = listOf(4, 7, 4)
    assert value.contains(7) panic "contains must find present values"
    assert value.indexOf(4) == 0 && value.lastIndexOf(4) == 2 panic "search positions changed"
    assert value.indexOf(9) == -1 panic "missing values must report -1"
}

test "list slices and reversal return independent orderings" {
    fin value = listOf(1, 2, 3, 4)
    fin middle = value.subList(1, 3)
    fin rev = value.reversed
    assert middle.size == 2 && middle.get(0) == 2 && middle.get(1) == 3 panic "subList bounds are half-open"
    assert rev.get(0) == 4 && rev.get(3) == 1 panic "reversed order changed"
    assert value.get(0) == 1 panic "derived lists must not mutate the source"
}

test "mutable list clear permits reuse" {
    var value = mutableListOf(1, 2)
    value.clear()
    value.add(9)
    assert value.size == 1 && value.get(0) == 9 panic "cleared lists must remain reusable"
}

test .All "list"

