impl LinkedHashMap<K, V> {
    /** `[k: v, …]` where a `LinkedHashMap<K, V>` is expected, in literal order; a repeated key keeps its last value. */
    literal [...entries: (K, V)]: LinkedHashMap<K, V> {
        return _linkedHashMapOf(entries)
    }

    ctor .() {
        for i in 0..<self.bucketCapacity {
            self.buckets[i] = -1
        }
    }

    dtor .() {
        using self { purge [keys, values, hashes, buckets] }
    }

    func &._findIndex(key: K&): Int {
        fin hash = key.hash
        var bucket = (hash % (self.bucketCapacity as ULong)) as Int
        for visited in 0..<self.bucketCapacity {
            fin index = self.buckets[bucket]
            if index < 0 {
                return -1
            }
            if self.hashes[index] == hash && self.keys[index] == key {
                return index
            }
            bucket = (bucket + 1) % self.bucketCapacity
        }
        return -1
    }

    func !._insertBucket(index: Int) {
        var bucket = (self.hashes[index] % (self.bucketCapacity as ULong)) as Int
        while self.buckets[bucket] >= 0 {
            bucket = (bucket + 1) % self.bucketCapacity
        }
        self.buckets[bucket] = index
    }

    func !._rebuildBuckets(newCapacity: Int) {
        fin oldBuckets = self.buckets
        self.buckets = alloc .() * newCapacity
        self.bucketCapacity = newCapacity
        var i = 0
        while i < newCapacity {
            self.buckets[i] = -1
            i += 1
        }
        i = 0
        while i < self._size {
            self._insertBucket(i)
            i += 1
        }
        purge oldBuckets
    }

    func !._growEntries() {
        fin newCapacity = self.capacity * 2
        let newKeys: K* = alloc .() * newCapacity
        let newValues: V* = alloc .() * newCapacity
        let newHashes: ULong* = alloc .() * newCapacity
        for i in 0..<self._size {
            newKeys[i] = self.keys[i]
            newValues[i] = self.values[i]
            newHashes[i] = self.hashes[i]
        }
        fin oldKeys = self.keys
        fin oldValues = self.values
        fin oldHashes = self.hashes
        self.keys = newKeys
        self.values = newValues
        self.hashes = newHashes
        self.capacity = newCapacity
        purge oldKeys
        purge oldValues
        purge oldHashes
    }

    func !._putValue(key: K, value: V): V? {
        fin found = self._findIndex(key)
        if found >= 0 {
            fin previous = self.values[found]
            self.values[found] = value
            return previous
        }
        if self._size >= self.capacity {
            self._growEntries()
        }
        if (self._size + 1) * 10 >= self.bucketCapacity * 7 {
            self._rebuildBuckets(self.bucketCapacity * 2)
        }
        fin hash = key.hash
        self.keys[self._size] = key
        self.values[self._size] = value
        self.hashes[self._size] = hash
        self._insertBucket(self._size)
        self._size += 1
        return null
    }

    func !._removeValue(key: K&): V? {
        fin found = self._findIndex(key)
        if found < 0 {
            return null
        }
        fin previous = self.values[found]
        for i in found..<self._size - 1 {
            self.{keys[i], values[i], hashes[i]} = using self {
                {keys[i + 1], values[i + 1], hashes[i + 1]}
            }
        }
        self._size -= 1
        self._rebuildBuckets(self.bucketCapacity)
        return previous
    }

    func &._entrySnapshot(): Array<MapEntry<K, V>> {
        var result: Array<MapEntry<K, V>> = .() * self._size
        for i in 0..<self._size {
            result[i] = MapEntry(self.keys[i], self.values[i])
        }
        return result
    }
}

