// TreeMap implementation (AVL balanced tree)
// ---------------------------------------------------------------------

impl TreeMap<K, V> {
    /** `[k: v, …]` where a `TreeMap<K, V>` is expected. A repeated key keeps its last value. */
    literal [...entries: (K, V)]: TreeMap<K, V> {
        var result: TreeMap<K, V> = .()
        for i in 0..<entries.size {
            result.put(entries[i].0, entries[i].1)
        }
        return result
    }

    dtor .() {
        using self { purge [keys, values, left, right, parent, heights, freeNext] }
    }

    func &._elemHeight(elem: Int): Int {
        if elem < 0 {
            return 0
        }
        return self.heights[elem]
    }

    func !._updateHeight(elem: Int) {
        if elem < 0 {
            return
        }
        fin leftHeight = self._elemHeight(self.left[elem])
        fin rightHeight = self._elemHeight(self.right[elem])
        self.heights[elem] = if leftHeight > rightHeight {
            leftHeight + 1
        } else {
            rightHeight + 1
        }
    }

    func !._grow() {
        fin newCapacity = self.capacity * 2
        let {
            newKeys: K*
            newValues: V*
            newLeft: Int*
            newRight: Int*
            newParent: Int*
            newHeights: Int*
            newFreeNext: Int*
        } = alloc .() * newCapacity

        for i in 0..<self.elemCount {
            {newKeys[i], newValues[i], newLeft[i], newRight[i]
            newParent[i], newHeights[i], newFreeNext[i]} = using self {
                {keys[i], values[i], left[i], right[i], parent[i], heights[i], freeNext[i]}
            }
        }
        using self { purge [keys, values, left, right, parent, heights, freeNext] }
        self.{keys, values, left, right, parent, heights, freeNext, capacity} =
            {newKeys, newValues, newLeft, newRight, newParent, newHeights, newFreeNext, newCapacity}
    }

    func !._allocateNode(key: K, value: V, parent: Int): Int {
        var elem = self.freeHead
        if elem >= 0 {
            self.freeHead = self.freeNext[elem]
        } else {
            if self.elemCount >= self.capacity {
                self._grow()
            }
            elem = self.elemCount
            self.elemCount += 1
        }
        self.{keys[elem], values[elem], left[elem], right[elem], parent[elem], heights[elem]} =
            {key, value, -1, -1, parent, 1}
        self._size += 1
        return elem
    }

    func !._releaseNode(elem: Int) {
        self.{freeNext[elem], freeHead} = {self.freeHead, elem}
        self._size -= 1
    }

    func !._replaceParentChild(parent: Int, oldChild: Int, newChild: Int) {
        if parent < 0 {
            self.root = newChild
        } else if self.left[parent] == oldChild {
            self.left[parent] = newChild
        } else {
            self.right[parent] = newChild
        }
        if newChild >= 0 {
            self.parent[newChild] = parent
        }
    }

    func !._rotateLeft(elem: Int): Int {
        fin {pivot, oldParent}: Int = {self.right[elem], self.parent[elem]}
        self.right[elem] = self.left[pivot]
        if self.right[elem] >= 0 {
            self.parent[self.right[elem]] = elem
        }
        self.{left[pivot], parent[elem], parent[pivot]} = {elem, pivot, oldParent}
        self._replaceParentChild(oldParent, elem, pivot)
        self._updateHeight(elem)
        self._updateHeight(pivot)
        return pivot
    }

    func !._rotateRight(elem: Int): Int {
        fin {pivot, oldParent}: Int = {self.left[elem], self.parent[elem]}
        self.left[elem] = self.right[pivot]
        if self.left[elem] >= 0 {
            self.parent[self.left[elem]] = elem
        }
        self.{right[pivot], parent[elem], parent[pivot]} = {elem, pivot, oldParent}
        self._replaceParentChild(oldParent, elem, pivot)
        self._updateHeight(elem)
        self._updateHeight(pivot)
        return pivot
    }

    func !._rebalanceFrom(start: Int) {
        var elem = start
        while elem >= 0 {
            self._updateHeight(elem)
            fin balance = self._elemHeight(self.left[elem]) - self._elemHeight(self.right[elem])
            if balance > 1 {
                if self._elemHeight(self.left[self.left[elem]]) < self._elemHeight(self.right[self.left[elem]]) {
                    self._rotateLeft(self.left[elem])
                }
                fin top = self._rotateRight(elem)
                elem = self.parent[top]
            } else if balance < -1 {
                if self._elemHeight(self.right[self.right[elem]]) < self._elemHeight(self.left[self.right[elem]]) {
                    self._rotateRight(self.right[elem])
                }
                fin top = self._rotateLeft(elem)
                elem = self.parent[top]
            } else {
                elem = self.parent[elem]
            }
        }
    }

    func &._findNode(key: K&): Int {
        var elem = self.root
        while elem >= 0 {
            if key < self.keys[elem] {
                elem = self.left[elem]
            } else if self.keys[elem] < key {
                elem = self.right[elem]
            } else {
                return elem
            }
        }
        return -1
    }

    func !._putValue(key: K, value: V): V? {
        if self.root < 0 {
            self.root = self._allocateNode(key, value, -1)
            return null
        }
        var elem = self.root
        var parent = -1
        while elem >= 0 {
            parent = elem
            if key < self.keys[elem] {
                elem = self.left[elem]
            } else if self.keys[elem] < key {
                elem = self.right[elem]
            } else {
                fin previous = self.values[elem]
                self.values[elem] = value
                return previous
            }
        }
        fin inserted = self._allocateNode(key, value, parent)
        if key < self.keys[parent] {
            self.left[parent] = inserted
        } else {
            self.right[parent] = inserted
        }
        self._rebalanceFrom(parent)
        return null
    }

    func &._minimumNode(start: Int): Int {
        var elem = start
        if elem < 0 {
            return -1
        }
        while self.left[elem] >= 0 {
            elem = self.left[elem]
        }
        return elem
    }

    func &._maximumNode(start: Int): Int {
        var elem = start
        if elem < 0 {
            return -1
        }
        while self.right[elem] >= 0 {
            elem = self.right[elem]
        }
        return elem
    }

    func !._removeValue(key: K&): V? {
        var elem = self._findNode(key)
        if elem < 0 {
            return null
        }
        fin previous = self.values[elem]

        if self.left[elem] >= 0 && self.right[elem] >= 0 {
            fin successor = self._minimumNode(self.right[elem])
            self.keys[elem] = self.keys[successor]
            self.values[elem] = self.values[successor]
            elem = successor
        }

        fin child = if self.left[elem] >= 0 {
            self.left[elem]
        } else {
            self.right[elem]
        }
        fin oldParent = self.parent[elem]
        self._replaceParentChild(oldParent, elem, child)
        self._releaseNode(elem)
        self._rebalanceFrom(oldParent)
        return previous
    }

    func &._entrySnapshot(): Array<MapEntry<K, V>> {
        var result: Array<MapEntry<K, V>> = .() * self._size
        let stack: Int* = alloc .() * self._size
        var stackSize = 0
        var elem = self.root
        var output = 0
        while elem >= 0 || stackSize > 0 {
            while elem >= 0 {
                stack[stackSize] = elem
                stackSize += 1
                elem = self.left[elem]
            }
            stackSize -= 1
            elem = stack[stackSize]
            result[output] = MapEntry(self.keys[elem], self.values[elem])
            output += 1
            elem = self.right[elem]
        }
        purge stack
        return result
    }
}

