impl SortedMap<K, V> for TreeMap<K, V> {
    func &.firstKey(): K? {
        fin elem = self._minimumNode(self.root)
        if elem < 0 {
            return null
        }
        return self.keys[elem]
    }

    func &.lastKey(): K? {
        fin elem = self._maximumNode(self.root)
        if elem < 0 {
            return null
        }
        return self.keys[elem]
    }

    func &.lowerKey(key: K&): K? {
        var elem = self.root
        var candidate = -1
        while elem >= 0 {
            if self.keys[elem] < key {
                candidate = elem
                elem = self.right[elem]
            } else {
                elem = self.left[elem]
            }
        }
        if candidate < 0 {
            return null
        }
        return self.keys[candidate]
    }

    func &.floorKey(key: K&): K? {
        fin exact = self._findNode(key)
        if exact >= 0 {
            return self.keys[exact]
        }
        return self.lowerKey(key)
    }

    func &.ceilingKey(key: K&): K? {
        fin exact = self._findNode(key)
        if exact >= 0 {
            return self.keys[exact]
        }
        return self.higherKey(key)
    }

    func &.higherKey(key: K&): K? {
        var elem = self.root
        var candidate = -1
        while elem >= 0 {
            if key < self.keys[elem] {
                candidate = elem
                elem = self.left[elem]
            }
            else {
                elem = self.right[elem]
            }
        }
        if candidate < 0 {
            return null
        }
        return self.keys[candidate]
    }

    func &.firstEntry(): MapEntry<K, V>? {
        fin elem = self._minimumNode(self.root)
        if elem < 0 {
            return null
        }
        return MapEntry(self.keys[elem], self.values[elem])
    }

    func &.lastEntry(): MapEntry<K, V>? {
        fin elem = self._maximumNode(self.root)
        if elem < 0 {
            return null
        }
        return MapEntry(self.keys[elem], self.values[elem])
    }

    func &.headMap(toKey: K&, inclusive: Bool = false): SortedMap<K, V> {
        var result: TreeMap<K, V> = .()
        fin all = self._entrySnapshot()
        for i in 0..<all.size {
            fin beforeEnd = all[i].key < toKey || (inclusive && !(toKey < all[i].key))
            if beforeEnd {
                result.put(all[i].key, all[i].value)
            }
        }
        return result
    }

    func &.tailMap(fromKey: K&, inclusive: Bool = true): SortedMap<K, V> {
        var result: TreeMap<K, V> = .()
        fin all = self._entrySnapshot()
        for i in 0..<all.size {
            fin afterStart = fromKey < all[i].key || (inclusive && !(all[i].key < fromKey))
            if afterStart {
                result.put(all[i].key, all[i].value)
            }
        }
        return result
    }

    func &.subMap(
        fromKey: K&, fromInclusive: Bool
        toKey: K&, toInclusive: Bool
    ): SortedMap<K, V>
    in {
        assert !(toKey < fromKey) panic "subMap start must not be greater than end"
    } scope {
        var result: TreeMap<K, V> = .()
        fin all = self._entrySnapshot()
        for i in 0..<all.size {
            fin afterStart = fromKey < all[i].key || (fromInclusive && !(all[i].key < fromKey))
            fin beforeEnd = all[i].key < toKey || (toInclusive && !(toKey < all[i].key))
            if afterStart && beforeEnd {
                result.put(all[i].key, all[i].value)
            }
        }
        return result
    }
}

impl MutableSortedMap<K, V> for TreeMap<K, V> {
    func !.pollFirstEntry(): MapEntry<K, V>? {
        fin elem = self._minimumNode(self.root)
        if elem < 0 {
            return null
        }
        fin result: MapEntry = .(self.keys[elem], self.values[elem])
        self._removeValue(self.keys[elem])
        return result
    }

    func !.pollLastEntry(): MapEntry<K, V>? {
        fin elem = self._maximumNode(self.root)
        if elem < 0 {
            return null
        }
        fin result: MapEntry = .(self.keys[elem], self.values[elem])
        self._removeValue(self.keys[elem])
        return result
    }
}

