// ---------------------------------------------------------------------

/** What `Map` and `MutableMap` literals build: the entries in order, a repeated key keeping its last value. */
func<K, V> _linkedHashMapOf(entries: Array<(K, V)>): LinkedHashMap<K, V> where K: Hash {
    var result: LinkedHashMap<K, V> = .()
    for i in 0..<entries.size {
        result.put(entries[i].0, entries[i].1)
    }
    return result
}

@Experimental(since: "0.1")
func<K, V> mapEntry(key: K, value: V): MapEntry<K, V> {
    return MapEntry(key, value)
}

/**
 * Infix constructor for a [MapEntry].
 *
 * `1 @to "a"` is sugar for `mapEntry(1, "a")`, so map factories read
 * naturally: `hashMapOf(1 to "a", 2 to "b")`.
 */
@Experimental(since: "0.1")
macro $a @to $b => mapEntry($a, $b)

@Experimental(since: "0.1")
func<K, V> hashMapOf(...entries: MapEntry<K, V>): HashMap<K, V> where K: Hash {
    var result: HashMap<K, V> = .()
    for i in 0..<entries.size {
        result.put(entries[i].key, entries[i].value)
    }
    return result
}

@Experimental(since: "0.1")
func<K, V> linkedHashMapOf(...entries: MapEntry<K, V>): LinkedHashMap<K, V> where K: Hash {
    var result: LinkedHashMap<K, V> = .()
    for i in 0..<entries.size {
        result.put(entries[i].key, entries[i].value)
    }
    return result
}

@Experimental(since: "0.1")
func<K, V> treeMapOf(...entries: MapEntry<K, V>): TreeMap<K, V> where K: Order {
    var result: TreeMap<K, V> = .()
    for i in 0..<entries.size {
        result.put(entries[i].key, entries[i].value)
    }
    return result
}

/**
 * Builds a read-only `Map<K, V>` from the supplied entries.
 *
 * Mirrors Kotlin's `mapOf`: the backing store is an insertion-ordered
 * `LinkedHashMap`, exposed through the read-only `Map` view. Equal keys
 * keep the last supplied value.
 */
@Experimental(since: "0.1")
func<K, V> mapOf(...entries: MapEntry<K, V>): Map<K, V> where K: Hash {
    var result: LinkedHashMap<K, V> = .()
    for i in 0..<entries.size {
        result.put(entries[i].key, entries[i].value)
    }
    return result
}

/**
 * Builds a `MutableMap<K, V>` from the supplied entries.
 *
 * Mirrors Kotlin's `mutableMapOf`: the backing store is an insertion-ordered
 * `LinkedHashMap`, exposed through the `MutableMap` view. Equal keys keep
 * the last supplied value.
 */
@Experimental(since: "0.1")
func<K, V> mutableMapOf(...entries: MapEntry<K, V>): MutableMap<K, V> where K: Hash {
    var result: LinkedHashMap<K, V> = .()
    for i in 0..<entries.size {
        result.put(entries[i].key, entries[i].value)
    }
    return result
}

