// Operators
// ---------------------------------------------------------------------

@Experimental(since: "0.1")
oper[] HashMap<K, V>&.(key: K): V {
    return self.get(key)
}

@Experimental(since: "0.1")
oper[]= HashMap<K, V>!.(key: K, value: V) {
    self.put(key, value)
}

@Experimental(since: "0.1")
oper[] LinkedHashMap<K, V>&.(key: K): V {
    return self.get(key)
}

@Experimental(since: "0.1")
oper[]= LinkedHashMap<K, V>!.(key: K, value: V) {
    self.put(key, value)
}

@Experimental(since: "0.1")
oper[] TreeMap<K, V>&.(key: K): V {
    return self.get(key)
}

@Experimental(since: "0.1")
oper[]= TreeMap<K, V>!.(key: K, value: V) {
    self.put(key, value)
}

/** Slicing is over current iteration order and returns an ordered snapshot. */
@Experimental(since: "0.1")
oper[:] HashMap<K, V>&.(slice: MapSlice): Map<K, V> {
    assert slice.step != 0 panic "Map slice step cannot be zero"
    fin all = self.entries()
    var result: LinkedHashMap<K, V> = .()
    var i = slice.start
    while (slice.step > 0 && i < slice.end) || (slice.step < 0 && i > slice.end) {
        if i >= 0 && i < all.size {
            result.put(all[i].key, all[i].value)
        }
        i += slice.step
    }
    return result
}

@Experimental(since: "0.1")
oper[:] LinkedHashMap<K, V>&.(slice: MapSlice): Map<K, V> {
    assert slice.step != 0 panic "Map slice step cannot be zero"
    var result: LinkedHashMap<K, V> = .()
    var i = slice.start
    while (slice.step > 0 && i < slice.end) || (slice.step < 0 && i > slice.end) {
        if i >= 0 && i < self._size {
            result.put(self.keys[i], self.values[i])
        }
        i += slice.step
    }
    return result
}

@Experimental(since: "0.1")
oper[:] TreeMap<K, V>&.(slice: MapSlice): Map<K, V> {
    assert slice.step != 0 panic "Map slice step cannot be zero"
    fin all = self.entries()
    // A sorted map's slice is sorted too, and needs `K` ordered rather than hashed.
    var result: TreeMap<K, V> = .()
    var i = slice.start
    while (slice.step > 0 && i < slice.end) || (slice.step < 0 && i > slice.end) {
        if i >= 0 && i < all.size {
            result.put(all[i].key, all[i].value)
        }
        i += slice.step
    }
    return result
}

@Experimental(since: "0.1")
oper+ HashMap<K, V>&.(entry: MapEntry<K, V>): Map<K, V> {
    var result = hashMapOf<K, V>()
    result.putAll(self)
    result.put(entry.key, entry.value)
    return result
}

@Experimental(since: "0.1")
oper- HashMap<K, V>&.(key: K): Map<K, V> {
    var result = hashMapOf<K, V>()
    result.putAll(self)
    result.remove(key)
    return result
}

@Experimental(since: "0.1")
oper+ LinkedHashMap<K, V>&.(entry: MapEntry<K, V>): Map<K, V> {
    var result = linkedHashMapOf<K, V>()
    result.putAll(self)
    result.put(entry.key, entry.value)
    return result
}

@Experimental(since: "0.1")
oper- LinkedHashMap<K, V>&.(key: K): Map<K, V> {
    var result = linkedHashMapOf<K, V>()
    result.putAll(self)
    result.remove(key)
    return result
}

@Experimental(since: "0.1")
oper+ TreeMap<K, V>&.(entry: MapEntry<K, V>): Map<K, V> {
