@Experimental(since: "0.1")
oper- TreeMap<K, V>&.(key: K): Map<K, V> {
    var result = treeMapOf<K, V>()
    result.putAll(self)
    result.remove(key)
    return result
}

@Experimental(since: "0.1")
oper== HashMap<K, V>&.(rhs: Map<K, V>): Bool {
    if self._size != rhs.size {
        return false
    }
    fin all = self.entries()
    for i in 0..<all.size {
        if !rhs.containsKey(all[i].key) || rhs.get(all[i].key) != all[i].value {
            return false
        }
    }
    return true
}

@Experimental(since: "0.1")
oper!= HashMap<K, V>&.(rhs: Map<K, V>): Bool {
    return !(self == rhs)
}

@Experimental(since: "0.1")
impl HashMap<K, V> {
    prop &.hash: ULong {
        fin all = self.entries()
        var result = 0 as ULong
        for i in 0..<all.size {
            result += ((all[i].key.hash as ULong) ^ (all[i].value.hash as ULong))
        }
        return result
    }
}

