// A LinkedHashSet has no `hash` until an element's `Hash` can be required and called
// through a generic slot; `.hash` on an unconstrained `T` has no implementation.

test "set starts empty" {
    fin value: TreeSet<Int> = .()
    assert value.size == 0 && value.isEmpty panic "emptySet must contain no values"
}

test "setOf removes duplicates" {
    fin value = setOf(1, 2, 1, 3, 2)
    assert value.size == 3 panic "setOf must retain unique values only"
    assert value.get(0) == 1 && value.get(1) == 2 && value.get(2) == 3 panic "set insertion order changed"
}

test "mutableSetOf removes duplicates" {
    fin value = mutableSetOf(1, 2, 1)
    assert value.size == 2 && value.contains(1) && value.contains(2) panic "mutableSetOf uniqueness changed"
}

test "set add reports whether membership changed" {
    var value = mutableSetOf(1)
    assert !value.add(1) panic "adding a duplicate must be a no-op"
    assert value.add(2) panic "adding a new value must report a change"
    assert value.size == 2 panic "set size must count unique values"
}

test "set remove preserves remaining membership" {
    var value = mutableSetOf(1, 2, 3)
    assert value.remove(2) panic "remove must report an existing value"
    assert !value.remove(9) panic "remove must report a missing value"
    assert value.size == 2 && !value.contains(2) panic "removed values must disappear"
}

test "set algebra produces unique results" {
    fin left = setOf(1, 2, 3)
    fin right = setOf(3, 4)
    fin combined = left.union(right)
    fin common = left.intersect(right)
    fin difference = left.difference(right)
    assert combined.size == 4 && combined.contains(4) panic "union must contain both memberships"
    assert common.size == 1 && common.contains(3) panic "intersection must contain shared values"
    assert difference.size == 2 && difference.contains(1) && difference.contains(2) panic "difference must exclude right values"
}

test "set grows without losing uniqueness" {
    var value = LinkedHashSet<Int>()
    for i in 0..<20 {
        value.add(i % 10)
    }
    assert value.size == 10 && value.contains(9) panic "growth must preserve ten unique values"
}

test "set clear permits reuse" {
    var value = mutableSetOf(1, 2)
    value.clear()
    value.add(7)
    assert value.size == 1 && value.contains(7) panic "cleared sets must remain reusable"
}

test "set serialization metadata is declared" {
    inline assert reflect<LinkedHashSet>.hasAnnot<Serializable> panic "LinkedHashSet must carry Serializable metadata"
}

test .All "set"

