/**
 * Very-high-accuracy counterparts of the `std` math functions.
 *
 * `sin` and friends are the everyday choice: on WebAssembly they are software
 * approximations carrying float precision, which is what shader-adjacent and
 * simulation code wants and costs the least. `vha::sin` names the same
 * mathematical function computed to the full accuracy the platform can offer, for
 * the places where error accumulates - long-running integrators, geodesy, anything
 * iterating a transform thousands of times.
 *
 * Every backend supplies these directly. On native and interpreted targets both
 * tiers already resolve to the platform's double-precision routine, so `vha` costs
 * nothing there; only WebAssembly distinguishes them.
 *
 * @since 0.1
 */
scope vha {
    /** Sine of [x] (radians), to full platform accuracy. */
    bridge func sin(x: Double): Double
    /** Cosine of [x] (radians), to full platform accuracy. */
    bridge func cos(x: Double): Double
    /** Tangent of [x] (radians), to full platform accuracy. */
    bridge func tan(x: Double): Double
    /** Arc sine of [x] in radians, to full platform accuracy; [x] must be in [-1, 1]. */
    bridge func asin(x: Double): Double
    /** Arc cosine of [x] in radians, to full platform accuracy; [x] must be in [-1, 1]. */
    bridge func acos(x: Double): Double
    /** Arc tangent of [x] in radians, to full platform accuracy. */
    bridge func atan(x: Double): Double
    /** Angle (radians) of the point (x, y), to full platform accuracy. */
    bridge func atan2(y: Double, x: Double): Double
    /** Cube root of [x], to full platform accuracy. */
    bridge func cbrt(x: Double): Double
    /** Natural (base-e) logarithm of [x], to full platform accuracy. */
    bridge func log(x: Double): Double
    /** Base-2 logarithm of [x], to full platform accuracy. */
    bridge func log2(x: Double): Double
    /** Base-10 logarithm of [x], to full platform accuracy. */
    bridge func log10(x: Double): Double
    /** e raised to the power [x], to full platform accuracy. */
    bridge func exp(x: Double): Double
    /** 2 raised to the power [x], to full platform accuracy. */
    bridge func exp2(x: Double): Double
    /** sqrt(x*x + y*y) without overflow/underflow, to full platform accuracy. */
    bridge func hypot(x: Double, y: Double): Double
}

