/**
 * @file std/memory/slice.az
 *
 * Bounds-carrying view over a contiguous pointer range.
 *
 * @since 0.1
 */
@Supress(.Unused)
module std.memory.slice

@Since("0.1")
pack Slice<T> {
    var _raw: T*
    var count: Int
}

@Experimental(since: "0.1")
oper[] Slice<T>&.(index: Int): T {
    assert index >= 0 && index < self.count panic "Slice index out of bounds"
    return self._raw[index]
}

@Experimental(since: "0.1")
oper[]= Slice<T>!.(index: Int, value: T) {
    assert index >= 0 && index < self.count panic "Slice index out of bounds"
    self._raw[index] = value
}

impl Slice<T> {
    /** `true` when the slice has no elements. */
    @Since("0.1")
    prop &.isEmpty: Bool = self.count == 0

    /** `true` when the slice has at least one element. */
    @Since("0.1")
    prop &.isNotEmpty: Bool = self.count > 0

    /** Returns the raw underlying `T*`. */
    @Since("0.1")
    prop &.ptr: T* = self._raw

    /** Returns a sub-slice `[start, start+count)`; asserts bounds. */
    @Experimental(since: "0.1")
    func &.sub(start: Int, count: Int): Slice<T> {
        assert start >= 0 panic "Slice start must be non-negative"
        assert count >= 0 panic "Slice count must be non-negative"
        assert start + count <= self.count panic "Slice range out of bounds"
        return Slice(self._raw + start, count)
    }
}

/** Constructs a `Slice<T>` over [length] elements starting at [ptr]. */
@Experimental(since: "0.1")
func<T> sliceOf(ptr: T*, length: Int): Slice<T> {
    return Slice(ptr, length)
}

/** Alias of [sliceOf]. */
@Experimental(since: "0.1")
func<T> ptrSlice(ptr: T*, length: Int): Slice<T> {
    return sliceOf(ptr, length)
}

