/**
 * @file std/memory/weak
 *
 * Non-owning pointer view. It never drops memory; callers must prove the
 * pointee outlives the weak view.
 *
 * @since 0.1
 */
@Supress(.Unused)
module std.memory.weak

@Since("0.1")
pack Weak<T> {
    var _raw: T*
}

@Experimental(since: "0.1")
oper.* Weak<T>&.(): T { // here we need to implement mandatory deref...
    assert self._raw != null panic "Weak pointer is null"
    return self._raw.*
}

/**
 * Cloning a `Weak` duplicates the non-owning handle, never the object. It is
 * not `Copy`: a weak handle is still a thing you decide to make another of.
 */
@Since("0.1")
impl Clone for Weak<T> {
    func &.clone() { // return type must be specified mandatory, it is not Unit, fix in compiler
        return Weak<T>(self._raw)
    }
}

impl Weak<T> {
    /** Returns the referenced value (panics if the pointer is null). */
    @Experimental(since: "0.1")
    prop &.get: T {
        assert self._raw != null panic "Weak pointer is null"
        return self._raw.*
    }

    /** Returns the raw `T*` (may be null). */
    @Since("0.1")
    prop &.ptr: T* = self._raw

    /** `true` when the pointer is null (does not own a reference). */
    @Since("0.1")
    prop &.isNull: Bool = self._raw == null
}

/** Wraps a raw `T*` as a non-owning `Weak<T>`. */
@Experimental(since: "0.1")
func<T> weakOf(ptr: T*): Weak<T> {
    return Weak(ptr)
}

